"""
Fix TS6133 build error: 'customer' was destructured from the Paystack
event payload in api/paystack-webhook.ts but never used. noUnusedLocals
in tsconfig.json caught it at build time. Removed it from the
destructure -- the type definition (customer: { email: string }) stays,
since it still documents the real payload shape even though we don't
currently read that field.

Run on your Windows machine with the repo already cloned.
"""
import base64, os, subprocess, sys

DEFAULT_REPO = r"C:\\Users\\Bosslady\\SCHOLACORE\\scholacore"

FILE_REL = "api/paystack-webhook.ts"
FILE_B64 = ''


def run(cmd, cwd):
    print(">", " ".join(cmd))
    result = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True)
    if result.stdout.strip():
        print(result.stdout)
    if result.returncode != 0 and result.stderr.strip():
        print(result.stderr)
    return result.returncode == 0


def main():
    repo_root = sys.argv[1] if len(sys.argv) > 1 else DEFAULT_REPO
    if not os.path.isdir(repo_root):
        print(f"Repo path not found: {repo_root}")
        sys.exit(1)
    if not os.path.isdir(os.path.join(repo_root, ".git")):
        print(f"{repo_root} is not a git repository (no .git folder). Aborting.")
        sys.exit(1)

    dest = os.path.join(repo_root, FILE_REL)
    with open(dest, "wb") as f:
        f.write(base64.b64decode(FILE_B64))
    print(f"wrote: {FILE_REL}")

    run(["git", "add", FILE_REL], repo_root)
    commit_msg = "Fix TS6133: remove unused customer destructure in paystack-webhook.ts"
    if not run(["git", "commit", "-m", commit_msg], repo_root):
        print("Nothing to commit or commit failed -- check output above.")
        sys.exit(1)
    run(["git", "push", "origin", "main"], repo_root)


if __name__ == "__main__":
    main()
